<?php $channelNames=\App\Models\PaymentModel::CHANNELS; ?>
<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>我的订单</title><link rel="stylesheet" href="/assets/css/style.css"><style>
.orders-page{min-height:100vh;background:#f7f8fb;padding:18px 14px 108px}.orders-shell{max-width:860px;margin:0 auto}.orders-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:4px 0 14px}.orders-title{font-size:24px;font-weight:950;color:#0f172a;margin:0}.orders-head a{text-decoration:none}.orders-list{display:grid;gap:10px}.order-card{background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:15px;box-shadow:0 10px 28px rgba(15,23,42,.045)}.order-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.order-no{font-size:13px;font-weight:950;color:#0f172a;word-break:break-all}.order-time{font-size:12px;color:#94a3b8;margin-top:4px}.status{flex:0 0 auto;border-radius:999px;padding:5px 10px;font-size:12px;font-weight:950}.status.paid{background:#dcfce7;color:#15803d}.status.pending{background:#fef3c7;color:#b45309}.status.cancelled,.status.failed{background:#fee2e2;color:#b91c1c}.order-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.order-grid div{background:#f8fafc;border-radius:14px;padding:10px}.order-grid span{display:block;color:#94a3b8;font-size:12px;font-weight:850}.order-grid strong{display:block;margin-top:4px;color:#111827;font-size:14px;font-weight:950}.order-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.order-actions a{text-decoration:none}.empty{display:grid;place-items:center;text-align:center;color:#94a3b8;background:#fff;border:1px dashed #cbd5e1;border-radius:18px;padding:60px 16px}@media(max-width:640px){.orders-title{font-size:22px}.order-top{display:grid}.order-grid{grid-template-columns:1fr}.orders-head{align-items:flex-start}.orders-head .btn{white-space:nowrap}}html[data-theme="dark"] .orders-page{background:#0f172a}html[data-theme="dark"] .orders-title,html[data-theme="dark"] .order-no,html[data-theme="dark"] .order-grid strong{color:#e5e7eb}html[data-theme="dark"] .order-card,html[data-theme="dark"] .empty{background:#11182