</style></head><body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="orders-page"><div class="orders-shell"><div class="orders-head"><h1 class="orders-title">我的订单</h1><a class="btn btn-light" href="/index.php?path=wallet">返回钱包</a></div><?php if(!empty($orders)): ?><div class="orders-list"><?php foreach($orders as $o): ?><?php $status=(string)($o['status']??'pending'); $statusText=['pending'=>'待支付','paid'=>'已支付','cancelled'=>'已取消','failed'=>'失败'][$status]??$status; ?><article class="order-card"><div class="order-top"><div><div class="order-no"><?= htmlspecialchars($o['order_no']) ?></div><div class="order-time"><?= htmlspecialchars((string)$o['created_at']) ?></div></div><span class="status <?= htmlspecialchars($status) ?>"><?= htmlspecialchars($statusText) ?></span></div><div class="order-grid"><div><span>充值到账</span><strong><?= currency_trim_amount($o['amount']) ?> <?= htmlspecialchars($o['currency_name'] ?: currency_name_by_code((string)$o['currency_code'])) ?></strong></div><div><span>支付金额</span><strong><?= currency_trim_amount($o['pay_amount'],2) ?> 元</strong></div><div><span>支付方式</span><strong><?= htmlspecialchars($channelNames[$o['channel']] ?? $o['channel']) ?></strong></div></div><div class="order-actions"><a class="btn btn-light" href="/index.php?path=payment/order&order_no=<?= urlencode((string)$o['order_no']) ?>"><?= $status==='pending'?'继续支付 / 同步状态':'查看订单' ?></a><?php if($status==='pending'): ?><a class="btn btn-light" href="/index.php?path=wallet/recharge&currency=<?= urlencode((string)$o['currency_code']) ?>">重新充值</a><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><div class="empty"><div><strong>暂无充值订单</strong><p>充值后订单会显示在这里，方便继续支付和查看到账状态。</p><a class="btn" href="/index.php?path=wallet/recharge">去充值</a></div></div><?php endif; ?></div></main><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?><?php require __DIR__ . '/../layouts/bottom-nav.php'; ?></body></html>
